description:
Bump in lockstep — all 15 packages ship under one version. Don't use
`pnpm -r exec npm version` here — it implicitly runs `npm install`, which
trips on the optional zod peer dep. Direct JSON write is simpler and
deterministic:

```bash
node -e '
const fs = require("fs");
const PKGS = [
  "packages/mcp-server/package.json",
  ...["alibaba","anthropic","cost","elevenlabs","fal","fireworks","free","ig","kie","kimicoding","openai","polymarket","x","xai"]
    .map(p => "packages/provider/" + p + "/package.json"),
];
for (const p of PKGS) {
  const pkg = JSON.parse(fs.readFileSync(p, "utf8"));
  pkg.version = "0.1.0-alpha.0";
  fs.writeFileSync(p, JSON.stringify(pkg, null, 2) + "\n");
}
const wrong = PKGS.filter(p => JSON.parse(fs.readFileSync(p, "utf8")).version !== "0.1.0-alpha.0");
if (wrong.length) { console.log("WRONG:", wrong); process.exit(1); }
console.log("✓ all 15 at 0.1.0-alpha.0");
'
```

**Commit the bump:**
```bash
git add packages/mcp-server/package.json packages/provider/*/package.json
git commit -m "chore(release): @apicity/* → 0.1.0-alpha.0"
```

**Exit criteria:** All 15 package.json files at `0.1.0-alpha.0`, change committed.

Confirm every publishable package has the metadata it needs to ship cleanly.

Use `command grep` (not the alias — many shells alias `grep` to `ugrep` which has different flags) and explicit paths via `find` (not `ls -d`, which is aliased to `eza`/`lsd` in many environments and prints columns, not paths).

```bash
node -e '
const fs = require("fs");
const PKGS = [
  "packages/mcp-server",
  ...["alibaba","anthropic","cost","elevenlabs","fal","fireworks","free","ig","kie","kimicoding","openai","polymarket","x","xai"]
    .map(p => "packages/provider/" + p),
];
let bad = 0;
for (const p of PKGS) {
  const pkg = JSON.parse(fs.readFileSync(p + "/package.json", "utf8"));
  if (pkg.private === true) { console.log("✗ private:true in", p); bad++; }
  if (!(pkg.publishConfig && pkg.publishConfig.access === "public"))
    { console.log("✗ missing publishConfig.access=public in", p); bad++; }
  if (!fs.existsSync(p + "/LICENSE"))
    { console.log("✗ missing LICENSE in", p); bad++; }
}
if (bad === 0) console.log("✓ all 15 packages publish-ready");
process.exit(bad === 0 ? 0 : 1);
'
```

If any of these fail, the prep work was not completed. STOP. File a bug
referencing the parent epic and abort the release — pour again once prep is
green.

**Exit criteria:** All 15 packages pass all three checks.
